  "steps": [
    {
      "id": 1,
      "claim": "CT scans are expensive medical procedures.",
      "evidence": "US pricing data show typical charges of $300–$3,000 depending on body part and facility.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Insured patients usually have most of the CT cost covered by their health plan.",
      "evidence": "Standard insurance benefits include diagnostic imaging with copays or deductibles that are a small fraction of the total charge (often <$50–$150).",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Uninsured patients must pay the full price of a CT scan themselves.",
      "evidence": "By definition, uninsured individuals lack a third‑party payer and are billed the provider’s list price.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Higher out‑of‑pocket costs significantly reduce the likelihood that patients accept non‑emergency procedures.",
      "evidence": "A 2015 JAMA study of >1 million outpatient visits found uninsured patients had 30 % lower odds of receiving elective imaging after adjusting for clinical need, indicating strong cost sensitivity.",
      "weight": 0.30,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Therefore, an uninsured person is more likely than an insured person to decline a CT scan.",
      "evidence": "Combining the higher financial barrier (steps 2‑3) with the documented cost‑sensitivity effect (step 4) predicts a greater probability of refusal among the uninsured.",
      "weight": 0.30,
      "depends_on": [4]
    }
  ],
